// Shared by the tools/intl generators: the provenance header every generated .inc starts with.
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

// "// Generated by tools/intl/<script> (cd tools/intl && node <script>) with node X (ICU Y, CLDR Z, tz T,
// Unicode U), cldr-core V, cldr-bcp47 W. Do not edit."
export function header(script) {
  const v = process.versions;
  const pkg = (name) => require(`${name}/package.json`).version;
  return [
    `// Generated by tools/intl/${script}: cd tools/intl && npm install && node ${script}`,
    `// node ${v.node} (ICU ${v.icu}, CLDR ${v.cldr}, tz ${v.tz}, Unicode ${v.unicode}); cldr-core ${pkg('cldr-core')}, cldr-bcp47 ${pkg('cldr-bcp47')}.`,
    '// Do not edit; re-run the script (output is deterministic).',
  ].join('\n');
}

// Byte-order comparison (no locale collation) for deterministic sorting.
export const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
